function presentationProposal(){return `<aside class="presentation-proposal" aria-labelledby="presentation-proposal-title">
  <h3 id="presentation-proposal-title">Головна ідея сервісу — робота над собою разом із ШІ.</h3>
  <p class="presentation-proposal-intro">До цілісної картини власного життя користувач може йти різними шляхами: починає з тієї вкладки, яка зараз для нього найактуальніша, а агент підказує наступний крок. Три типові шляхи:</p>
  <div class="presentation-proposal-paths">
    ${PATHS.map(([title,entry,text,chain],i)=>`<section><span class="presentation-proposal-number">${two(i+1)}</span><h4>${title}</h4><p class="presentation-proposal-entry">${entry}</p><p>${text}</p><p class="presentation-proposal-chain">${chain}</p></section>`).join('')}
  </div>
  <p class="presentation-proposal-common">У кожному з цих шляхів ШІ-агент є помічником користувача: він пропонує, що записати, а користувач підтверджує. Усе записане стає контекстом для аналітики.</p>
</aside>`;}
function presentationIntro(){return `<section id="slide-1" class="presentation-section presentation-intro" data-slide="1" aria-labelledby="slide-title-1"><section class="hero"><div><h2 id="slide-title-1" class="slide-heading" tabindex="-1"><a href="#main"><strong>AboutIAmI</strong></a> це сервіс задля нової якості роботи над <em>ідеями, цілями та планами</em> користувача.</h2><p>ШІ відкриває нову еру людини, розширюючи можливості втілювати задуми та розуміти себе.</p><p>У сервісі шість вкладок і ШІ-агент. Усе, що користувач записує у вкладках, стає контекстом для агента, а агент — головним інструментом роботи з цим контекстом.</p></div></section>${presentationProposal()}<div class="dock"><p class="sectiontitle intro-direction"><span>Нижче</span> — опис агента та кожної вкладки сервісу.</p><div class="actions">${route('slides/2','Далі · '+nextSlideLabel(slides[1][0]),'primary','arr')}</div></div></section>`;}
function deckSection(n) {
  if(n===1) return presentationIntro();
  const [tag,title,body,more,sample,rows,dest,pid]=slides[n-1];
  const finalBody=tag==='Наступний крок'?`<div class="deck-final">
      <div class="kicker">${logo}<span>${tag}</span></div>
      <h2 id="slide-title-${n}" class="slide-heading visually-hidden" tabindex="-1">${title}</h2>
      <div class="actions deck-final__actions">${route('home','Макет сайту','primary deck-final__btn','arr')}${route('demo/'+lastTab(),'Макет застосунку','primary deck-final__btn','arr')}${route('main','На головну','deck-final__btn','arr')}</div>
    </div>`:null;
  return `<section id="slide-${n}" class="presentation-section${finalBody?' presentation-final':''}" data-slide="${n}" aria-labelledby="slide-title-${n}">
    ${finalBody?finalBody:`<div class="deckbody">
      <div>
        <div class="kicker">${logo}<span>${tag}</span></div>
        <h2 id="slide-title-${n}" class="slide-heading" tabindex="-1">${title}</h2>
        <p class="lede">${body}</p><p>${more}</p>
      </div>
      <div class="visual">
        <div class="micro">Демонстраційний приклад</div>
        <h3 class="smalltitle">${sample}</h3>
        ${rows.map(x=>{const [a,b]=x.split('|');return `<div class="sampleline"><b>${a}</b>${b.startsWith('~')?`<span class="sample-link">${b.slice(1)}</span>`:`<span>${b}</span>`}</div>`}).join('')}
        ${slideGraphic(tag)}
        <div class="actions">${route('demo/'+(dest==='cards'?'cards/0':dest),'Спробувати в макеті','','out')}</div>
        <a class="textbtn vis-note" href="#screens/${pid}/0">Переглянути екран продукту</a>
      </div>
    </div>`}
    ${finalBody||n===slides.length-1?'':`<div class="dock">
      <a class="quiet" href="#${n===1?'main':'slides/'+(n-1)}">${ic('back')} Назад</a>
      <div class="actions">${route('slides/'+(n+1),'Далі · '+nextSlideLabel(slides[n][0]),'primary','arr')}</div>
    </div>`}
  </section>`;
}

function deck(n) {
  return `<main id="content" class="bound deckintro" tabindex="-1">
    <h1 class="visually-hidden">Детальна презентація складових сервісу AboutIAmI</h1>
    <div class="presentation-toolbar">
      <div class="bar"><span>Детальна презентація &nbsp; / &nbsp; <b class="count">${two(n)} з ${two(slides.length)}</b></span>${btn('toc',ic('list')+' Зміст')}</div>
      <nav class="segments" aria-label="Слайди">${slides.map((s,i)=>`<a href="#slides/${i+1}" aria-label="Слайд ${i+1}. ${s[0]}" class="${i<n?'visited':''}" ${i+1===n?'aria-current="location"':''}></a>`).join('')}</nav>
    </div>
    ${slides.map((_,i)=>deckSection(i+1)).join('')}
  </main>`;
}

