function home() {
  return `<main id="content" class="bound product-home" tabindex="-1">
    <nav class="home-nav" aria-label="Знайомство із сервісом">${brand}<div class="home-nav-links"><a href="#home/idea" data-home-scroll="idea">Ідея</a><a href="#home/parts" data-home-scroll="parts">Як це працює</a>${route('demo/entry','Вхід','primary','out')}</div></nav>
    <section class="home-hero"><div><div class="kicker home-kicker"><span>Сервіс для думаючих людей</span></div><h1 class="home-title">AboutIAmI — <em>працюй над собою з ШІ</em>.</h1><p class="home-lead">${E(HOME_CONTENT.texts['hero-title'].value)}</p><div class="home-prose">${homeCopy('hero-body')}</div><div class="actions">${route('demo/entry','Вхід','primary','out')}<a class="home-textlink" href="#home/parts" data-home-scroll="parts">Як це працює <span aria-hidden="true">↓</span></a></div></div>${homeArt()}</section>
    <section class="home-section" id="home-idea"><div class="home-grid"><div><div class="home-eyebrow"><span>01</span> Про сервіс</div><h2>Життя у цілісній картині</h2></div><div class="home-prose">${homeCopy('overview')}</div></div></section>
    <section class="home-section" id="home-parts"><div class="home-eyebrow"><span>02</span> Як це працює</div><h2 tabindex="-1">Шість вкладок і ШІ-агент.</h2><div class="home-features"><div class="home-feature-tabs" role="tablist" aria-label="Частини сервісу">${HOME_CONTENT.features.map((f,i)=>`<button type="button" id="home-tab-${f.code}" role="tab" aria-selected="${f.code===homeFeature}" aria-controls="home-feature-panel" tabindex="${f.code===homeFeature?'0':'-1'}" data-home-feature="${f.code}"><span>${two(i+1)}</span>${f.name}</button>`).join('')}</div><section id="home-feature-panel" class="home-feature-content" role="tabpanel" tabindex="0" aria-labelledby="home-tab-${homeFeature}">${homeFeaturePanel(homeFeature)}</section></div></section>
    <section class="home-section home-agent" id="home-agent"><div class="home-grid"><div><div class="home-eyebrow"><span>03</span> ШІ-агент</div><h2>Твій помічник — ШІ-агент.</h2><div class="home-prose">${homeCopy('ai-intro')}</div></div><div class="home-theory home-prose">${homeCopy('ai-theory')}</div></div></section>
    <section class="home-closing"><div class="home-prose" lang="en">${homeCopy('slogan')}</div>${route('demo/entry','Вхід','primary','out')}</section>
    ${homeFooter()}
  </main>`;
}
function selectHomeFeature(code) {
  if (!HOME_CONTENT.features.some(f=>f.code===code)) return;
  homeFeature=code;
  document.querySelectorAll('.home-feature-tabs [role=tab]').forEach(tab=>{
    const selected=tab.dataset.homeFeature===code;
    tab.setAttribute('aria-selected',String(selected));
    tab.tabIndex=selected?0:-1;
  });
  const panel=$('#home-feature-panel');
  panel.innerHTML=homeFeaturePanel(code);
  panel.setAttribute('aria-labelledby','home-tab-'+code);
}
function scrollHomeSection(id,smooth=true) {
  const section=$('#home-'+id);
  if(!section) return;
  section.querySelector('h2')?.focus({preventScroll:true});
  section.scrollIntoView({behavior:smooth&&!matchMedia('(prefers-reduced-motion:reduce)').matches?'smooth':'instant',block:'start'});
}
document.addEventListener('click',e=>{
  const feature=e.target.closest('[data-home-feature]');
  if(feature){selectHomeFeature(feature.dataset.homeFeature);if(feature.hasAttribute('data-home-art'))scrollHomeSection('parts');return;}
  const link=e.target.closest('[data-home-scroll]');
  if(link&&e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();scrollHomeSection(link.dataset.homeScroll);}
});
document.addEventListener('keydown',e=>{
  const tab=e.target.closest('.home-feature-tabs [role=tab]');
  if(!tab||!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key))return;
  e.preventDefault();
  const features=HOME_CONTENT.features,index=features.findIndex(f=>f.code===tab.dataset.homeFeature);
  const next=e.key==='Home'?0:e.key==='End'?features.length-1:(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:features.length-1))%features.length;
  selectHomeFeature(features[next].code);
  $('#home-tab-'+features[next].code).focus();
});

