/* Підрахунки з метрик */
const mCount=m=>m.baseline+m.events.reduce((s,e)=>s+e.v,0);
const mPct=m=>m.goal?Math.min(100,Math.round(mCount(m)*100/m.goal)):null;
const mText=m=>m.goal?`${mCount(m)} з ${m.goal} ${E(m.unit)}`:`${mCount(m)} ${E(m.unit)}`;
const live=c=>c.mode==='metrics'?c.metrics:[];
const cardPct=c=>{const ms=live(c).filter(m=>m.goal);return ms.length?Math.round(ms.reduce((s,m)=>s+mPct(m),0)/ms.length):null};
const hasRecords=c=>live(c).some(m=>mCount(m)>0);
const avgPct=()=>{const e=st.cards.map(cardPct).filter(p=>p!==null);return e.length?Math.round(e.reduce((s,p)=>s+p,0)/e.length):null};
