function agent(){
  const open=agentOpen||matchMedia('(min-width:768px) and (min-height:500px)').matches;
  const chips=pending?[['agent-yes','так'],['agent-no','ні, скасуй']]:chat.length===1?[['agent-start','Розпочинаємо'],['agent-guide','Дай ще кілька підказок']]:[['agent-record','Сьогодні було заняття з англійської'],['agent-report','Як мої справи з цілями?'],['agent-decide','Запиши моє рішення']];
  return `<details class="agent" ${open?'open':''}><summary>${ic('agent')} Переписка з агентом</summary>
    <div class="chatlog" aria-live="polite">${chat.map(m=>`<div class="msg ${m.who==='a'?'from-agent':'from-user'}${m.ok?' ok':''}">${m.lines.map((l,k)=>`<p>${m.ok&&!k?ic('check'):''}${E(l)}</p>`).join('')}</div>`).join('')}</div>
    <div class="chatchips"><span class="hint">${pending?'Твоя відповідь':'Приклади повідомлень у макеті'}</span>${chips.map(([a,t])=>btn(a,E(t))).join('')}</div>
    <form id="chatform" class="composer"><label class="visually-hidden" for="chatinput">Повідомлення агенту</label><input id="chatinput" name="text" maxlength="300" placeholder="Можна написати…" autocomplete="off"><button type="submit" class="iconbtn" title="Надіслати">${ic('send')}<span class="visually-hidden">Надіслати</span></button></form>
  </details>`;
}

/* 01 Декларація */
function declaration(){
  return `${pageHead(0)}${st.section.map((s,i)=>`<section class="decl"><h2>${E(s.title)}</h2><div class="brk"><p>${E(s.body)}</p>${s.comments.length?`<ul class="comments">${s.comments.map(c=>`<li><span>${E(c.t)}</span><small>${fmtD(c.d)}</small></li>`).join('')}</ul>`:''}</div><div class="rowbtns">${btn('comment:'+i,ic('plus')+' Коментар')}${btn('editsection:'+i,ic('pen')+' Редагувати')}</div></section>`).join('')||'<p class="hint">Декларація ще порожня. Тут записується твоє бачення: як ти дивишся на світ, ким себе відчуваєш, який шлях обираєш і на що спираєшся. Почати можна кнопкою «Додати розділ».</p>'}<div class="center">${btn('newsection','Додати розділ','button primary')}</div>`;
}

/* 02 План: три горизонти, пункти з підпунктами, бажаною датою та зв’язком із карткою */
function plan(){
  return `${pageHead(1)}${HZ.map(([h,sub],i)=>{
    const items=st.plans.map((p,j)=>[p,j]).filter(([p])=>p.h===i);
    return `<section class="horizon"><h2>${h}<small>${sub}</small></h2>${items.map(([p,j])=>`<div class="planrow brk"><label class="checkrow"><input type="checkbox" data-plan="${j}" ${p.done?'checked':''}><span>${E(p.t)}</span></label><span class="planmeta">${p.d?`<span class="plandate">${fmtIso(p.d)}</span>`:''}${p.c!==null&&st.cards[p.c]?`<button type="button" class="planlink" data-act="showcard:${p.c}" title="Відкрити пов’язану картку">${ic('link')}<span>${E(st.cards[p.c].name)}</span></button>`:''}</span><span class="rowtools">${iconbtn('editplan:'+j,'pen','Редагувати пункт')}${iconbtn('newsub:'+j,'plus','Додати підпункт')}</span></div>${(p.sub||[]).map((s,k)=>`<div class="planrow sub brk"><label class="checkrow"><input type="checkbox" data-plan="${j}.${k}" ${s.done?'checked':''}><span>${E(s.t)}</span></label></div>`).join('')}`).join('')||'<p class="hint">Тут ще немає пунктів. Перший можна додати кнопкою «+».</p>'}${btn('newplan:'+i,ic('plus')+' Додати пункт')}</section>`;
  }).join('')}`;
}

/* 03 Картки: колода, лицьовий бік (навіщо, пріоритет, мотив) і зворот (метрики або стан) */
function cardFront(c){
  const m=motiveOf(c);
  return `<p class="meaning">${E(c.meaning)||'<span class="hint">Опис ще не додано.</span>'}</p><div class="cardmeta">${m?`<span class="motiveflag" style="background:${m.color};color:${m.ink}">${E(m.name)}</span>`:'<span class="hint">без мотиву</span>'}<span class="prio">${PRIOS[c.priority][0]}</span>${c.mode==='state'?stateChip(c.state):''}</div>`;
}
function cardBack(c){
  if(c.mode==='state')return `<p class="micro">Режим: стан без вимірювань</p><div class="statechips" role="group" aria-label="Стан картки">${STATES.map((s,k)=>`<button type="button" data-act="setstate:${k}" aria-pressed="${c.state===s}">${E(s)}</button>`).join('')}</div><p>${btn('mode:metrics','Вести з цілями та метриками','textbtn')}</p>`;
  const p=cardPct(c),events=c.metrics.flatMap(m=>m.events.map(e=>({...e,m}))).sort((a,b)=>b.date-a.date);
  return `${btn('metric',ic('plus')+' Додати метрику','button wide')}${p!==null?`<div class="cardprog"><b>Прогрес картки: ${p}%</b>${meter(p)}</div>`:''}${c.metrics.map((m,k)=>`<div class="metric brk"><div class="spread"><strong>${E(m.name)}</strong><span>${mText(m)}${m.goal?' · '+mPct(m)+'%':''}</span></div>${m.goal?meter(mPct(m)):''}<div class="rowtools">${btn('record:'+k,ic('plus')+' Запис')}</div></div>`).join('')||`<p class="hint">Метрика — це те, що ти рахуєш для цієї сфери життя: наприклад, кілометри пробіжки чи прочитані книги. До метрики можна поставити ціль і строк.</p><p>${btn('mode:state','Вести без вимірювань — через стан','textbtn')}</p>`}${events.length?`<details class="history"><summary>Історія записів (${events.length})</summary>${events.map(e=>`<div class="logline"><small>${fmtD(e.date)}</small><span>+${e.v} ${E(e.m.unit)} · ${E(e.m.name)}</span></div>`).join('')}</details>`:''}`;
}
function cards(){
  const c=card(),others=st.cards.map((_,i)=>i).filter(i=>i!==st.card);
  return `${pageHead(2)}<div class="deck"><div class="decktabs">${others.map((i,k)=>`<button type="button" data-act="showcard:${i}" style="margin-inline:${(others.length-k)*9}px">${E(st.cards[i].name)}</button>`).join('')}</div>
    <section class="lifecard" aria-label="Картка «${E(c.name)}», ${flipped?'зворот':'лицьовий бік'}">
      <div class="spread"><h2>${E(c.name)}</h2>${iconbtn('editcard','dots','Налаштування картки')}</div>
      ${flipped?cardBack(c):cardFront(c)}
      <div class="flipwrap">${btn('flip',flipped?ic('back')+' перегорнути':'перегорнути '+ic('arr'),'button')}</div>
    </section></div>
    <div class="cardnav">${iconbtn('precard','back','Попередня картка','smallbtn')}${iconbtn('nextcard','arr','Наступна картка','smallbtn')}${btn('newcard','Створити картку','button primary')}</div>`;
}

/* 04 Схема: розмір картки — пріоритет, картка під нею — мотив, мітка — стан */
const CSIZE=[[96,64],[116,78],[140,94]];
function schemeLayout(){
  const pos=[];
  if(st.layout==='focus'){
    const R=[],L=[];st.cards.forEach((c,i)=>(c.priority>0?R:L).push(i));
    R.sort((a,b)=>st.cards[b].priority-st.cards[a].priority);
    const ch=i=>(CSIZE[st.cards[i].priority]||CSIZE[0])[1],hh=i=>ch(i)+(motiveOf(st.cards[i])?16:0),gap=44;
    const tall=arr=>arr.reduce((s,i)=>s+hh(i),0)+gap*Math.max(arr.length-1,0),H=Math.max(tall(L),tall(R),1);
    const col=(arr,x)=>{let y=(H-tall(arr))/2;arr.forEach(i=>{pos[i]=[x,Math.round(y+ch(i)/2)];y+=hh(i)+gap})};
    col(L,150);col(R,450);
    return {pos,core:undefined,labels:[[150,'Тримаю в полі зору'],[450,'Активний фокус']],cols:[L,R]};
  }
  const core=st.cards[st.core]?st.core:0,others=st.cards.map((_,i)=>i).filter(i=>i!==core);
  const big=others.length>5,cx=320,cy=230,rx=big?250:228,ry=big?190:156;
  pos[core]=[cx,cy];
  others.forEach((i,k)=>{const a=(-150+360*k/others.length)*Math.PI/180;pos[i]=[Math.round(cx+rx*Math.cos(a)),Math.round(cy+ry*Math.sin(a))]});
  return {pos,core,labels:[]};
}
/* Точка, де лінія від картки i в напрямку картки j виходить з-під картки разом з її мотивом. */
function schemeEdge(pos,i,j){
  const c=st.cards[i],[w,h]=CSIZE[c.priority]||CSIZE[0],m=motiveOf(c)?1:0;
  const x=pos[i][0]+m*7,y=pos[i][1]+m*8,dx=pos[j][0]-x,dy=pos[j][1]-y;
  const t=Math.min(dx?(w/2+m*7)/Math.abs(dx):9,dy?(h/2+m*8)/Math.abs(dy):9,1);
  return [x+dx*t,y+dy*t];
}
function scheme(){
  const {pos,core,labels,cols}=schemeLayout();
  const conn=st.connections.filter(l=>st.cards[l.a]&&st.cards[l.b]);
  /* У стовпчику зв’язок між не сусідніми картками обходить їх дугою збоку. */
  const bend=l=>{if(!cols)return 0;for(const [s,arr] of [[-1,cols[0]],[1,cols[1]]]){const a=arr.indexOf(l.a),b=arr.indexOf(l.b);if(a>-1&&b>-1&&Math.abs(a-b)>1)return s}return 0};
  const midY=l=>Math.round((pos[l.a][1]+pos[l.b][1])/2);
  const linked=(a,b)=>conn.some(l=>(l.a===a&&l.b===b)||(l.a===b&&l.b===a));
  const thin=core===undefined?'':st.cards.map((_,i)=>i===core||linked(i,core)?'':`<path d="M${pos[core]} L${pos[i]}"/>`).join('');
  const marks=conn.map((l,k)=>{const s=bend(l),p=schemeEdge(pos,l.a,l.b),q=schemeEdge(pos,l.b,l.a),x=s?pos[l.a][0]+s*125:Math.round((p[0]+q[0])/2),y=s?midY(l):Math.round((p[1]+q[1])/2);return `<g><circle cx="${x}" cy="${y}" r="10" fill="#fff" stroke="#000"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" font-weight="700">${k+1}</text></g>`}).join('');
  let x1=1e9,y1=1e9,x2=-1e9,y2=-1e9;
  const nodes=st.cards.map((c,i)=>{
    const [x,y]=pos[i],[w,h]=CSIZE[c.priority]||CSIZE[0],m=motiveOf(c),x0=x-w/2,y0=y-h/2;
    x1=Math.min(x1,x0);y1=Math.min(y1,y0);x2=Math.max(x2,x0+w+14);y2=Math.max(y2,y0+h+16);
    const fs=[12.5,13.5,15][c.priority],max=[10,12,14][c.priority],name=c.name.length>max?c.name.slice(0,max-1)+'…':c.name;
    const mmax=Math.floor((w-14)/6.4),mname=m&&m.name.length>mmax?m.name.slice(0,mmax-1)+'…':m?.name;
    const mark=c.mode!=='state'?'':c.state==='використовується'?`<rect x="${x0+9}" y="${y0+h-23}" width="13" height="13" rx="2" fill="#006B50"/><circle cx="${x0+15.5}" cy="${y0+h-16.5}" r="2.6" fill="#fff"/>`:c.state==='критично потребує відновлення'?`<rect x="${x0+9}" y="${y0+h-23}" width="13" height="13" rx="2" fill="#AC5A3F"/><rect x="${x0+13}" y="${y0+h-19}" width="5" height="5" fill="#fff"/>`:`<rect x="${x0+9}" y="${y0+h-23}" width="13" height="13" rx="2" fill="#fff" stroke="#000" ${c.state?'':'stroke-dasharray="2 2"'}/><circle cx="${x0+15.5}" cy="${y0+h-16.5}" r="2.6" fill="none" stroke="#000"/>`;
    return `<a href="#demo/cards/${i}" aria-label="${E(c.name)}: ${PRIOS[c.priority][0].toLowerCase()}${m?', мотив «'+E(m.name)+'»':''}${c.mode==='state'&&c.state?', стан: '+E(c.state):''}">${m?`<rect x="${x0+14}" y="${y0+16}" width="${w}" height="${h}" rx="4" fill="${m.color}" stroke="#595959"/><text x="${x0+22}" y="${y0+h+12}" font-size="10.5" font-weight="650" fill="${m.ink}">${E(mname)}</text>`:''}<rect class="scard" x="${x0}" y="${y0}" width="${w}" height="${h}" rx="4" fill="#fff" stroke="${i===core?'#244bdb':'#595959'}" stroke-width="${i===core?2:1}"/><text x="${x0+9}" y="${y0+21}" font-size="${fs}" font-weight="700">${E(name)}</text>${mark}</a>`;
  }).join('');
  conn.forEach(l=>{const s=bend(l);if(s){const x=pos[l.a][0]+s*125;x1=Math.min(x1,x-12);x2=Math.max(x2,x+12)}});
  const pad=22,top=labels.length?34:pad,vx=Math.floor(x1-pad),vy=Math.floor(y1-top),vw=Math.ceil(x2-x1+pad*2),vh=Math.ceil(y2-y1+top+pad);
  return `${pageHead(3)}<div class="schemapad"><svg viewBox="${vx} ${vy} ${vw} ${vh}" style="max-width:${Math.round(vw*1.25)}px" role="group" aria-label="Схема: картки сфер життя та зв’язки між ними">${labels.map(([x,t])=>`<text x="${x}" y="${vy+16}" text-anchor="middle" font-size="11" font-weight="700" fill="#595959" letter-spacing=".06em">${t.toUpperCase()}</text>`).join('')}<g fill="none" stroke="#c9c9c9" stroke-width="1.2">${thin}</g><g fill="none" stroke="#000" stroke-width="1.5">${conn.map(l=>{const s=bend(l);return `<path d="M${pos[l.a]} ${s?`Q${pos[l.a][0]+s*250},${midY(l)}`:'L'} ${pos[l.b]}"/>`}).join('')}</g>${nodes}${marks}</svg></div>
    <p class="hint schemenote">${LAYOUTS.find(l=>l[0]===st.layout)?.[1]||LAYOUTS[0][1]}. Картка відкриває сферу у вкладці «Картки».</p>
    ${conn.length?`<ol class="connlist">${conn.map(l=>`<li><strong>${E(st.cards[l.a].name)} — ${E(st.cards[l.b].name)}</strong><span>${E(l.note)}</span></li>`).join('')}</ol>`:''}
    <div class="actions">${btn('config','Конфігурація','button')}${btn('connect','Додати зв’язок','button primary')}</div>`;
}

/* 05 Аналітика: чотири питання. Числа — з даних профілю, тексти в сервісі пише ШІ. */
function analytics(){
  const avg=avgPct(),unmeasured=st.cards.filter(c=>cardPct(c)===null).length;
  const goals=st.cards.map(c=>{const p=cardPct(c);return `<div class="arow brk"><div class="spread"><strong>${E(c.name)}</strong>${p!==null?`<b>${p}%</b>`:c.mode==='state'?stateChip(c.state):'<small class="hint">метрик ще нема</small>'}</div>${p!==null?meter(p):''}</div>`}).join('');
  const important=st.cards.filter(c=>c.priority>0).sort((a,b)=>b.priority-a.priority);
  const kept=c=>c.mode==='state'?c.state==='використовується':hasRecords(c);
  const focus=important.map(c=>`<div class="arow brk"><strong>${E(c.name)}</strong><span class="flag ${kept(c)?'ok':'attn'}">${kept(c)?(c.mode==='state'?'стан: використовується':'підтримується записами'):'Заявлено важливим, не підтримується'}</span></div>`).join('')||'<p class="hint">Жодна картка ще не має пріоритету.</p>';
  const open=st.plans.filter(p=>!p.done),dated=open.filter(p=>p.d).length,done=st.plans.filter(p=>p.done).length;
  const top=st.cards.filter(c=>c.priority===2);
  const declared=top.map(c=>c.mode==='state'?`«${E(c.name)}» має найвищий пріоритет і ведеться без вимірювань: ${E(c.state||'стан не обрано')}.`:hasRecords(c)?`«${E(c.name)}» має найвищий пріоритет, і записи це підтверджують.`:`«${E(c.name)}» має найвищий пріоритет, але записів у цій картці ще нема.`);
  const active=st.cards.filter(c=>c.priority<2&&hasRecords(c)).map(c=>'«'+E(c.name)+'»');
  if(active.length)declared.push(`Записи ведуться в картках: ${active.join(', ')}.`);
  const quote=(st.section[1]||st.section[0])?.body||'';
  return `${pageHead(4)}<div class="agrid">
    <section class="ablock"><h2>Цілі<small>Чи рухаюсь я до своїх цілей?</small></h2>
      ${avg!==null?`<p class="astat">Середній прогрес: <b>${avg}%</b></p>${meter(avg)}`:'<p class="hint">Ще нема карток із ціллю, яку можна рахувати.</p>'}
      ${unmeasured?`<p class="hint">Не враховано карток: ${unmeasured} (для них нічим міряти прогрес)</p>`:''}
      ${goals}
      <p class="hint">Шкала: червона — менше 30%, жовта — від 30% до 70%, зелена — від 70%.</p>
    </section>
    <section class="ablock"><h2>Фокус<small>Чи не втрачаю я фокус на важливому?</small></h2>
      ${focus}
      <div class="areport brk"><div class="micro">Оцінка «Навантаження» · План</div><p>Відкритих пунктів плану: ${open.length}. З бажаною датою: ${dated}. Виконано: ${done}.</p></div>
    </section>
    <section class="ablock"><h2>Задеклароване і реальне<small>Чи живу я так, як заявляю?</small></h2>
      <div class="areport brk"><div class="micro">Сценарний звіт · за поточними записами</div>${declared.length?declared.map(t=>`<p>${t}</p>`).join(''):'<p>Жодна картка ще не має найвищого пріоритету, тож зіставляти нема з чим.</p>'}${quote?`<p class="hint">У декларації: «${E(quote.length>280?quote.slice(0,279)+'…':quote)}»</p>`:''}</div>
    </section>
    <section class="ablock"><h2>Зміни й рішення<small>Що змінилось і які мої рішення?</small></h2>
      ${st.decisions.length?st.decisions.map(d=>`<div class="arow brk decision"><span>${E(d.t)}</span><small class="hint">${fmtD(d.d)}</small></div>`).join(''):'<p class="hint">Рішень ще не записано. Рішення можна зафіксувати разом з агентом.</p>'}
      ${st.log.length?`<div class="micro alast">Останні зміни</div>${st.log.slice(0,3).map(l=>`<div class="logline"><small>${fmtD(l.date)}</small><span>${E(l.s)}</span></div>`).join('')}`:''}
      <p>${btn('agent-decide','Записати рішення')}</p>
    </section>
  </div><div class="actions">${btn('report','Звіт за запитом','button primary')}${btn('log','Лог дій','button')}</div>`;
}

/* 06 Ресурси: посилання під картками сфер, окремо — ще не підключені */
function resources(){
  const row=r=>`<div class="resource brk">${ic('link')}${r.url?`<a href="${E(r.url)}" target="_blank" rel="noopener noreferrer">${E(r.title)}</a>`:btn('demolink',E(r.title),'textbtn')}${btn('resource:'+st.resources.indexOf(r),'Змінити','textbtn')}</div>`;
  const free=st.resources.filter(r=>!r.cards.some(i=>st.cards[i]));
  return `${pageHead(5)}<p>${btn('resource',ic('plus')+' Додати своє','button primary')}</p>${st.cards.map((c,i)=>`<section class="resgroup"><h2>${E(c.name)}</h2>${st.resources.filter(r=>r.cards.includes(i)).map(row).join('')||'<p class="hint">Посилань ще немає</p>'}</section>`).join('')}${free.length?`<section class="resgroup"><h2>Ще не підключені</h2>${free.map(row).join('')}</section>`:''}`;
}

function demo(tab){
  if(tab==='entry'||tab==='terms')return `<main id="content" tabindex="-1" class="bound"><div class="stage">${brand}<div class="kicker">Демонстраційний вхід</div><h1>${tab==='entry'?'Життя у цілісній картині':'Угода першого входу'}</h1><p>${tab==='entry'?'У продукті можна увійти через Google або за номером телефону. У макеті обидва способи відкривають тестовий профіль.':'У продукті перед початком роботи людина читає й приймає умови сервісу. Тут ти відкриваєш демонстраційний профіль. Зміни залишаються в цьому браузері.'}</p><div class="actions">${tab==='entry'?`${btn('login','Вхід через Google','button primary')}${btn('login','Увійти за номером телефону','button')}`:`${btn('accept','Погоджуюсь','button primary')}${route('demo/entry','Не погоджуюсь')}`}</div><p><a class="textlink" href="#screens/${tab==='entry'?'01':'02'}/0">Переглянути екран продукту</a></p></div></main>`;
  const idx=ids.indexOf(tab),body=[declaration,plan,cards,scheme,analytics,resources][idx]();
  return `<main class="bound" id="content" tabindex="-1"><div class="worktop spread"><span class="micro">Макет застосунку · демонстраційний профіль</span><div>${btn('tools','Можливості макета','quiet')}${btn('original:'+canon[idx],ic('grid')+' Екрани продукту','quiet')}</div></div>
    <div class="work">${agent()}<div class="mainpane"><div class="app-title"><a href="#home" aria-label="AboutIAmI, макет сайту">${brand}</a>${btn('settings',ic('gear')+' Налаштування','smallbtn')}</div><div class="workspace tab-${tab}">${body}</div><nav class="app-tabs" aria-label="Робочі вкладки">${ids.map((id,i)=>`<a ${idx===i?'aria-current="page"':''} href="#demo/${id}">${names[i]}</a>`).join('')}</nav></div></div>
    <div class="note-row">${storeFailed?'Зміни доступні до закриття сторінки.':'Зміни зберігаються у цьому браузері.'} <a class="textlink" href="#slides/${idx+3}">Опис вкладки в презентації</a></div></main>`;
}

function slideGraphic(tag){if(tag==='Картки')return `<div class="slide-meter"><div><b>6 <small>/ 12</small></b><span>занять з англійської</span></div><div class="ticks" aria-label="50 відсотків">${Array.from({length:12},(_,i)=>`<i class="${i<6?'on':''}"></i>`).join('')}</div></div>`;if(tag==='Схема')return `<svg class="slide-map" viewBox="0 0 410 90" role="img" aria-label="Зв’язок навчання з кар’єрою; мотив навчання — цікаво, мотив кар’єри — необхідно"><path fill="none" stroke="#8c8c8c" d="M116 33h56q7 0 7 7v6q0 7 7 7h87"/><rect x="20" y="24" width="110" height="46" rx="4" fill="#8FD19E" stroke="#333"/><text x="28" y="66" font-size="11" font-weight="650" font-family="Manrope,sans-serif" fill="#000">цікаво</text><rect x="287" y="44" width="112" height="38" rx="3" fill="#7A1F3D" stroke="#333"/><text x="295" y="78" font-size="11" font-weight="650" font-family="Manrope,sans-serif" fill="#fff">необхідно</text><rect x="6" y="10" width="110" height="46" rx="4" fill="white" stroke="#244bdb" stroke-width="2"/><rect x="273" y="30" width="112" height="38" rx="3" fill="white" stroke="#8c8c8c"/><g font-size="15" font-family="Manrope,sans-serif" text-anchor="middle"><text x="61" y="39">Навчання</text><text x="328" y="54">Кар’єра</text></g></svg>`;return ''}

let formCallback=null;const closeModal=(restore=true)=>{modal.replaceChildren();formCallback=null;document.body.style.overflow='';if(restore&&modalFocus?.isConnected)modalFocus.focus();modalFocus=null};
function openDialog(title,html,submit,saveLabel='Зберегти'){
const opener=document.activeElement;if(!modal.firstChild)modalFocus=opener;
formCallback=submit||null;modal.innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-labelledby="dialog-title" class="dialog"><div class="spread"><h2 id="dialog-title">${E(title)}</h2>${btn('close',ic('x')+'<span class="visually-hidden">Закрити</span>','close')}</div>${submit?`<form id="editform">${html}<div class="actions"><button type="submit" class="button primary">${saveLabel}</button>${btn('close','Скасувати')}</div></form>`:html}</section></div>`;document.body.style.overflow='hidden';(modal.querySelector('input:not([type="checkbox"]),textarea,select')||modal.querySelector('button')).focus()
}
function addEvent(c,m,v){m.events.push({v,date:Date.now()});log(`${c.name} · ${m.name}: +${v}`)}
const saveChanged=(msg)=>{save();closeModal(false);paint(false);if(msg)message(msg)};
/* Короткий підсумок за поточними записами: для агента й для «Звіту за запитом». */
function summaryLines(){
  const avg=avgPct(),out=[];
  if(avg!==null)out.push(`Середній прогрес карток із цілями — ${avg}%.`);
  st.cards.forEach(c=>{const p=cardPct(c);if(p!==null)out.push(`«${c.name}»: ${live(c).filter(m=>m.goal).map(m=>`${mCount(m)} з ${m.goal} ${m.unit}`).join(', ')} — ${p}%.`)});
  st.cards.filter(c=>c.priority===2&&c.mode==='metrics'&&!hasRecords(c)).forEach(c=>out.push(`«${c.name}» має найвищий пріоритет, але записів у цій картці ще нема.`));
  return out.length?out:['Записів поки мало, щоб робити висновки.'];
}
function showReport(){openDialog('Звіт за запитом',`<div class="micro">Сценарний звіт · поточні записи</div><h3>Чи рухаюсь я до своїх цілей?</h3>${summaryLines().map(l=>`<p>${E(l)}</p>`).join('')}<p class="hint">У сервісі текст звіту пише ШІ за твоїми записами. Що з цим робити, вирішуєш ти.</p><div class="actions">${btn('agent-decide','Записати своє рішення','button primary')}${btn('close','Закрити')}</div>`)}
function confirmPending(){
  if(!pending)return;
  const [c,m]=pending;pending=null;addEvent(c,m,1);
  sayA([`Записано 1 ${m.one||m.unit} у метриці «${m.name}» (картка «${c.name}»).`,`Зараз ${mCount(m)}${m.goal?' з '+m.goal:''} ${m.unit}.`],true);
  agentOpen=true;save();paint(false);message('Запис підтверджено. Аналітику оновлено.');
}
function doAction(a){
const [act,raw]=a.split(':'),i=Number(raw),c=card();
switch(act){
case 'close':closeModal();return;
case 'toc':openDialog('Зміст презентації',`<nav class="toc">${slides.map((s,j)=>`<a href="#slides/${j+1}" class="${j+1===activeSlide?'active':''}"><b class="smallnum">${two(j+1)}</b> &nbsp; ${E(s[0])}</a>`).join('')}</nav>`);return;
case 'original':location.hash='screens/'+raw+'/0';return;
case 'help':if(helpClosed.has(raw))helpClosed.delete(raw);else helpClosed.add(raw);paint(false);return;
case 'tools':openDialog('Можливості макета',`<p>У макеті можна дописувати декларацію, складати план із підпунктами, створювати картки й метрики, вносити записи, розкладати Схему, додавати ресурси та вести переписку з агентом за прикладами.</p><p>Справжнього ШІ в макеті нема: агент відповідає за сценарієм. Повний набір екранів і станів продукту — у каталозі.</p><div class="actions">${route('demo/entry','Пройти перший вхід')}${route('screens/01/0','Екрани продукту')}${route('slides/1','Детальна презентація')}</div>`);return;
case 'settings':openDialog('Налаштування макета',`<p>Дані цього прикладу зберігаються на твоєму пристрої.</p><div class="toc">${btn('log','Лог дій')}${btn('snapshot','Створити точку відновлення')}${btn('restore','Повернутися до точки')}${btn('reset','Почати приклад спочатку')}${route('screens/35/0','Екран «Налаштування правил» агента')}${route('demo/entry','Демонстраційний вхід')}</div>`);return;
case 'snapshot':try{localStorage.setItem(KEY+'.snapshot',JSON.stringify(st));closeModal();message('Точку відновлення створено')}catch{message('Цей браузер обмежує збереження даних')}return;
case 'restore':{let snap;try{snap=JSON.parse(localStorage.getItem(KEY+'.snapshot'))}catch{}if(!snap||snap.v!==2){message('Спочатку створи точку відновлення');return}openDialog('Повернутися до точки?',`<p>Буде відновлено збережений приклад на цьому пристрої.</p>`,()=>{st=snap;flipped=false;resetChat();log('Стан повернуто до точки');saveChanged('Дані відновлено')},'Повернути');return}
case 'reset':openDialog('Почати спочатку?',`<p>Поточні зміни буде замінено початковим демонстраційним прикладом.</p>`,()=>{st=baseState();flipped=false;resetChat();helpClosed.clear();saveChanged('Початковий приклад відновлено');location.hash='demo/declaration'},'Відновити приклад');return;
case 'login':location.hash=st.entered?'demo/'+lastTab():'demo/terms';return;
case 'accept':st.entered=true;save();location.hash='demo/declaration';return;

/* Декларація */
case 'newsection':{const used=st.section.map(s=>s.title),free=DECL_NAMES.filter(n=>!used.includes(n));openDialog('Новий розділ',select('Назва розділу','pick',[...free.map(n=>[n,n]),['','Власна назва']],free[0]??'')+field('Власна назва (якщо обрано «Власна назва»)','own','','text',false)+field('Яка твоя картина світу, ким себе відчуваєш і який шлях обираєш','body','','textarea'),d=>{const title=(d.get('pick')||d.get('own')||'').trim();if(!title){message('Обери назву зі списку або напиши свою');return}const obj={title,body:d.get('body').trim(),comments:[]};st.section.push(obj);log('Декларація · '+obj.title);saveChanged('Розділ збережено')},'Декларувати');return}
case 'editsection':{const old=st.section[i];openDialog('Редагувати розділ',field('Назва розділу','name',old.title)+field('Текст','body',old.body,'textarea'),d=>{old.title=d.get('name').trim();old.body=d.get('body').trim();log('Декларація · '+old.title);saveChanged('Розділ збережено')});return}
case 'comment':openDialog('Додати коментар',field('Твій коментар','value','','textarea'),d=>{st.section[i].comments.push({t:d.get('value').trim(),d:Date.now()});log('Додано коментар до декларації');saveChanged('Коментар збережено')});return;

/* План */
case 'newplan':case 'editplan':{const p=act==='editplan'?st.plans[i]:null;openDialog(p?'Редагувати пункт':'Новий пункт',field('Назва','name',p?.t)+select('Горизонт','h',HZ.map(([h,s],j)=>[j,h+' — '+s]),p?.h??i)+`<label class="field">Бажана дата виконання (необов’язково)<input name="d" type="date" value="${E(p?.d||'')}"></label>`+select('Зв’язок із карткою','c',[['','без зв’язку'],...cardOpts()],p?.c??''),d=>{const next={t:d.get('name').trim(),h:Number(d.get('h')),c:d.get('c')===''?null:Number(d.get('c')),d:d.get('d')||'',done:p?.done??false,sub:p?.sub||[]};if(p)st.plans[i]=next;else st.plans.push(next);log('План · '+next.t);saveChanged('Пункт збережено')});return}
case 'newsub':openDialog('Новий підпункт',`<p class="hint">${E(st.plans[i].t)}</p>`+field('Назва підпункту','name'),d=>{(st.plans[i].sub=st.plans[i].sub||[]).push({t:d.get('name').trim(),done:false});log('План · підпункт · '+d.get('name').trim());saveChanged('Підпункт додано')});return;

/* Картки */
case 'showcard':st.card=i;flipped=false;save();if(location.hash.startsWith('#demo/cards'))paint(false);else location.hash='demo/cards';return;
case 'flip':flipped=!flipped;paint(false);return;
case 'precard':case 'nextcard':st.card=(st.card+st.cards.length+(act==='precard'?-1:1))%st.cards.length;flipped=false;save();paint(false);return;
case 'newcard':case 'editcard':{const old=act==='editcard'?c:null;openDialog(old?'Налаштування картки':'Нова картка сфери життя',field('Назва','name',old?.name)+field('Опис (навіщо)','body',old?.meaning,'textarea',false)+select('Пріоритет','p',PRIOS.map(([n,h],k)=>[k,n+' — '+h]),old?.priority??0)+select('Мотив','motive',[['','без мотиву'],...st.motives.map(m=>[m.name,m.name])],old?.motive??'цікаво')+field('Або власний мотив','own','','text',false),d=>{const own=d.get('own').trim();if(own&&!st.motives.some(m=>m.name===own))st.motives.push({name:own,color:'#C9C9C9',ink:'#000'});const v=old||{mode:'metrics',state:'',metrics:[]};Object.assign(v,{name:d.get('name').trim(),meaning:d.get('body').trim(),motive:own||d.get('motive'),priority:Number(d.get('p'))});if(!old){st.cards.push(v);st.card=st.cards.length-1;flipped=false}log('Картка · '+v.name);saveChanged('Картку збережено')});return}
case 'metric':openDialog('Нова метрика',field('Що рахуємо/вимірюємо','name')+field('Одиниця','unit')+field('Ціль','goal','12','number'),d=>{const m={name:d.get('name').trim(),unit:d.get('unit').trim(),goal:Number(d.get('goal')),baseline:0,events:[]};c.mode='metrics';c.metrics.push(m);log('Додано метрику · '+m.name);saveChanged('Метрику додано')});return;
case 'record':{const m=c.metrics[i];if(!m)return;openDialog('Додати запис',`<p>${E(c.name)} · ${E(m.name)}</p>`+field('Значення ('+E(m.unit)+')','v','1','number'),d=>{addEvent(c,m,Number(d.get('v')));saveChanged('Запис додано. Аналітику оновлено.')},'Додати запис');return}
case 'setstate':c.state=c.state===STATES[i]?'':STATES[i];log(`${c.name} · стан: ${c.state||'не обрано'}`);save();paint(false);return;
case 'mode':c.mode=raw==='state'?'state':'metrics';log(`${c.name} · режим: ${c.mode==='state'?'стан без вимірювань':'з цілями та метриками'}`);save();paint(false);return;

/* Схема */
case 'connect':openDialog('Додати зв’язок',select('Перша картка','a',cardOpts(),0)+select('Друга картка','b',cardOpts(),1)+field('Коментар зв’язку','v','','textarea'),d=>{let a=Number(d.get('a')),b=Number(d.get('b'));if(a===b){message('Обери дві різні картки');return}let l=st.connections.find(l=>(l.a===a&&l.b===b)||(l.a===b&&l.b===a));if(l)l.note=d.get('v').trim();else st.connections.push({a,b,note:d.get('v').trim()});log('Збережено зв’язок карток');saveChanged('Зв’язок збережено')});return;
case 'config':openDialog('Конфігурація Схеми',`<p class="hint">Можна обрати, як розкласти картки.</p>`+select('Спосіб розкладки','layout',LAYOUTS.map(([k,n,h])=>[k,n+' — '+h]),st.layout)+select('Картка в центрі (для «Балансу навколо ядра»)','core',cardOpts(),st.core),d=>{st.layout=d.get('layout');st.core=Number(d.get('core'));log('Схема · '+LAYOUTS.find(l=>l[0]===st.layout)[1]);saveChanged('Розкладку застосовано')},'Застосувати');return;

/* Ресурси */
case 'resource':{let r=raw!==undefined?st.resources[i]:null;openDialog(r?'Змінити ресурс':'Додати своє',field('Назва','name',r?.title)+field('Посилання','url',r?.url,'url',!r||!!r.url)+`<fieldset><legend>Підключити до карток</legend>${cardOpts().map(([j,t])=>`<label class="checkrow"><input type="checkbox" name="cards" value="${j}" ${(r?r.cards.includes(j):false)?'checked':''}>${E(t)}</label>`).join('')}<p class="hint">Без жодної картки посилання потрапить у «Ще не підключені».</p></fieldset>`,d=>{let url=d.get('url').trim();if(url&&!/^https?:\/\//i.test(url)){message('Введи посилання з https:// або http://');return}let v={title:d.get('name').trim(),url,cards:d.getAll('cards').map(Number)};if(r)st.resources[i]=v;else st.resources.push(v);log('Ресурс · '+v.title);saveChanged('Ресурс збережено')});return}
case 'demolink':message('У макеті це умовне посилання. У сервісі воно відкриває твій сайт чи сервіс.');return;

/* Агент */
case 'agent-start':sayU('Розпочинаємо');sayA('У цьому прикладі профіль уже заповнено. Напиши, що сьогодні зроблено, — я запропоную запис, а ти підтвердиш його словом «так».');agentOpen=true;paint(false);return;
case 'agent-guide':sayU('Дай ще кілька підказок');sayA(GUIDE);agentOpen=true;paint(false);return;
case 'agent-record':{const t=agentTarget();sayU('Сьогодні було заняття з англійської');if(!t){sayA('У профілі ще нема метрики, куди це записати. Додай метрику на звороті картки.')}else{pending=t;sayA([`Записати 1 ${t[1].one||t[1].unit} у метрику «${t[1].name}» картки «${t[0].name}»?`,'Скажи «так» або уточни, що змінити.'])}agentOpen=true;paint(false);return}
case 'agent-yes':sayU('так');confirmPending();return;
case 'agent-no':sayU('ні, скасуй');pending=null;sayA('Добре, нічого не записую.');agentOpen=true;paint(false);return;
case 'agent-report':sayU('Як мої справи з цілями?');pending=null;sayA([...summaryLines(),'Докладніше — у вкладці «Аналітика».']);agentOpen=true;paint(false);return;
case 'agent-decide':openDialog('Записати рішення',field('Твоє рішення','v','','textarea'),d=>{const t=d.get('v').trim();st.decisions.unshift({t,d:Date.now()});log('Твоє рішення · '+t);sayU('Запиши моє рішення: '+t);sayA('Рішення записано. Воно видно в Аналітиці, у блоці «Зміни й рішення».',true);pending=null;agentOpen=true;saveChanged('Рішення збережено')},'Підтвердити запис');return;
case 'report':showReport();return;
case 'log':openDialog('Лог дій',st.log.map(l=>`<div class="logline"><small>${fmt(l.date)}</small><span>${E(l.s)}</span></div>`).join('')||'<p>Твої зміни з’являться тут після першої дії.</p>');return;
}}
const pageInfo=id=>CATALOG.find(p=>p.id===id)||CATALOG.find(p=>p.id==='04');
function gallery(id,n){const p=pageInfo(id),s=Math.max(0,Math.min(p.states.length-1,n||0));return `<main id="content" tabindex="-1" class="bound atlas"><div class="bar"><a class="quiet" href="#demo/${lastTab()}">${ic('back')} До робочого макета</a><span class="micro">Каталог екранів</span></div><h1 class="sectiontitle">Екрани сервісу</h1><p class="hint">Оригінальні макети з документації продукту. Обери екран та стан. Для внесення власних даних повернися до робочого макета.</p><div class="fields">${select('Екран','screen',CATALOG.map(p=>[p.id,p.title]),p.id)}${select('Стан','state',p.states.map((s,j)=>[j,s]),s)}</div><iframe title="${E(p.title)} · ${E(p.states[s])}" sandbox="allow-same-origin" id="original-screen"></iframe><p class="hint" id="atlasstatus">Відкриваємо екран…</p></main>`}
const assetCache=new Map();async function asset(path){if(!assetCache.has(path))assetCache.set(path,fetch(path).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).catch(e=>{assetCache.delete(path);throw e}));return assetCache.get(path)}
async function loadScreen(id,n,token){try{const p=pageInfo(id),s=Math.max(0,Math.min(p.states.length-1,n||0));const [base,page]=await Promise.all([asset('screens/base.json'),asset('screens/'+p.id+'.json')]);if(token!==atlasToken||!$('#original-screen'))return;$('#original-screen').srcdoc=`<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; font-src data:; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'"><style>${base.css}${page.css} body{margin:0} button,input,textarea,select,a,summary{pointer-events:none}</style></head><body>${base.icons}${page.states[s]}</body></html>`;$('#atlasstatus').textContent=`${p.title} · стан ${s+1} з ${p.states.length}`;}catch{if(token===atlasToken){$('#atlasstatus').innerHTML='Не вдалося завантажити екран. '+btn('retry','Спробувати ще раз')}}}
/* Маршрути: main — головна, home — макет сайту, demo — макет застосунку, slides — детальна презентація, screens — екрани продукту. */
function paint(move=true){let [group,arg,extra]=(location.hash.slice(1)||'main').split('/');let title='Головна';let body,navid='main';atlasToken++;
if(group==='slides' && $('.presentation-toolbar')) {
  scrollToSlide(Math.max(1,Math.min(slides.length,parseInt(arg)||1)));
  return;
}
if(group==='slides'){activeSlide=Math.max(1,Math.min(slides.length,parseInt(arg)||1));body=deck(activeSlide);title=slides[activeSlide-1][0];navid='slides'}
else if(group==='demo'){let tab=arg||lastTab();if(tab==='agent'){agentOpen=true;tab=lastTab()}if(!ids.includes(tab)&&!['entry','terms'].includes(tab))tab='declaration';if(tab==='cards'&&extra!==undefined&&location.hash!==lastHash){let k=Number(extra);if(Number.isInteger(k)&&st.cards[k]){st.card=k;flipped=false}}if(ids.includes(tab)){if(st.last!==tab)flipped=false;st.last=tab;save()}body=demo(tab);navid='demo';title=names[ids.indexOf(tab)]||'Вхід'}
else if(group==='screens'){let p=pageInfo(arg);body=gallery(p.id,Number(extra));title=p.title;navid='demo';loadScreen(p.id,Number(extra),atlasToken)}
else if(group==='home'){body=home();title='Макет сайту';navid='home'}
else{body=mainPage()}
root.innerHTML=nav(navid)+body+foot();document.title=title+' · AboutIAmI';lastHash=location.hash;
const chatlog=$('.chatlog');if(chatlog)chatlog.scrollTop=chatlog.scrollHeight;
if(group==='slides') { scrollToSlide(activeSlide,false); return; }
if(group==='home'&&arg) { scrollHomeSection(arg,false); return; }
if(move){window.scrollTo({top:0,behavior:'instant'});if(group==='demo'&&arg==='agent'&&matchMedia('(max-width:767px)').matches)document.querySelector('.agent')?.scrollIntoView({block:'center'})}}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#content')?.focus();return}let target=e.target.closest('[data-act]');if(target){let a=target.dataset.act;if(a==='retry')paint(false);else doAction(a);return}if(e.target.classList.contains('overlay'))closeModal();if(modal.contains(e.target)&&e.target.closest('a'))closeModal(false)});
document.addEventListener('change',e=>{let t=e.target;if(t.hasAttribute('data-plan')){const [j,k]=t.dataset.plan.split('.').map(Number),p=k===undefined?st.plans[j]:st.plans[j].sub[k];p.done=t.checked;log((p.done?'Виконано':'Знову відкрито')+' · '+p.t);save();message('План оновлено')}if(t.name==='screen')location.hash='screens/'+t.value+'/0';if(t.name==='state')location.hash='screens/'+document.querySelector('[name=screen]').value+'/'+t.value});
document.addEventListener('toggle',e=>{if(e.target.matches?.('details.agent'))agentOpen=e.target.open},true);
document.addEventListener('submit',e=>{
  if(e.target.id==='chatform'){e.preventDefault();const t=String(new FormData(e.target).get('text')||'').trim();if(!t)return;sayU(t);
    if(pending&&/^так[.!]*$/i.test(t)){confirmPending()}
    else{if(pending){pending=null;sayA('Добре, нічого не записую.')}else sayA('У макеті я відповідаю на приклади повідомлень нижче. У сервісі на будь-яке повідомлення відповідає ШІ: пропонує запис, а ти підтверджуєш його словом «так».');agentOpen=true;paint(false)}
    $('#chatinput')?.focus();return}
  if(e.target.id!=='editform')return;e.preventDefault();for(const f of e.target.querySelectorAll('input[required], textarea[required]'))if(!String(f.value).trim()){f.focus();message('Заповни обов’язкове поле');return}formCallback?.(new FormData(e.target))});
let slideScrollFrame=0;
let slideScrollTimer;

function syncSlidePosition() {
  const toolbar=$('.presentation-toolbar');
  if(!toolbar) return;
  const readingLine=toolbar.offsetHeight+Math.min(180,window.innerHeight*.2);
  let current=1;
  for(const section of document.querySelectorAll('.presentation-section')) {
    if(section.getBoundingClientRect().top<=readingLine) current=Number(section.dataset.slide);
  }
  activeSlide=current;
  toolbar.querySelector('.count').textContent=`${two(current)} з ${two(slides.length)}`;
  toolbar.querySelectorAll('.segments a').forEach((link,index)=>{
    link.classList.toggle('visited',index<current);
    if(index+1===current) link.setAttribute('aria-current','location');
    else link.removeAttribute('aria-current');
  });
  document.title=slides[current-1][0]+' · AboutIAmI';
}

function scrollToSlide(n,smooth=true) {
  const section=$('#slide-'+n);
  const toolbar=$('.presentation-toolbar');
  if(!section||!toolbar) return;
  const top=window.scrollY+section.getBoundingClientRect().top-toolbar.offsetHeight-12;
  const behavior=smooth&&!matchMedia('(prefers-reduced-motion:reduce)').matches?'smooth':'instant';
  section.querySelector('.slide-heading').focus({preventScroll:true});
  window.scrollTo({top,behavior});
  lastHash=location.hash;
  syncSlidePosition();
}

document.addEventListener('click',e=>{
  const link=e.target.closest('a[href^="#slides/"]');
  if(!link||!$('.presentation-toolbar')||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey) return;
  e.preventDefault();
  const hash=link.getAttribute('href');
  if(location.hash!==hash) history.pushState(null,'',hash);
  closeModal(false);
  scrollToSlide(Number(hash.split('/')[1]));
});

window.addEventListener('scroll',()=>{
  if(!$('.presentation-toolbar')) return;
  if(!slideScrollFrame) slideScrollFrame=requestAnimationFrame(()=>{
    slideScrollFrame=0;
    syncSlidePosition();
  });
  clearTimeout(slideScrollTimer);
  slideScrollTimer=setTimeout(()=>{
    if(!$('.presentation-toolbar')) return;
    syncSlidePosition();
    history.replaceState(null,'','#slides/'+activeSlide);
    lastHash=location.hash;
  },180);
},{passive:true});

function slideStep(dir){const next=activeSlide+dir;if(next>=1&&next<=slides.length){
  if(location.hash==='#slides/'+next) scrollToSlide(next);
  else location.hash='slides/'+next;
}}
document.addEventListener('keydown',e=>{if(modal.firstChild){if(e.key==='Escape')closeModal();if(e.key==='Tab'){let t=[...modal.querySelectorAll('a[href],button,input,textarea,select')];if(e.shiftKey&&document.activeElement===t[0]){e.preventDefault();t.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===t.at(-1)){e.preventDefault();t[0].focus()}}return}if(location.hash.startsWith('#slides/')&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();slideStep(e.key==='ArrowRight'?1:-1)}});
let touch;document.addEventListener('touchstart',e=>{touch=e.touches.length===1?[e.touches[0].clientX,e.touches[0].clientY]:null},{passive:true});document.addEventListener('touchend',e=>{if(!touch||modal.firstChild||!location.hash.startsWith('#slides/'))return;let x=e.changedTouches[0].clientX-touch[0],y=e.changedTouches[0].clientY-touch[1];touch=null;if(Math.abs(x)>75&&Math.abs(x)>Math.abs(y)*2)slideStep(x<0?1:-1)},{passive:true});
window.addEventListener('hashchange',()=>{closeModal(false);paint()});paint(false);
